-- Utilities bank_commands, part 2 (research/grafts/util_bank_commands, docs/game/ui/bank-commands.md §2): the retail
-- «Tabla de habilidades» (ability_learning_board_menu_7.00.00.00) opened for a player who is in no slot of the dock
-- the screen was given (the bank's «Tabla de habilidades»: the VS team as context, the player from the bank).
--
-- Owner, 2026-10-14: opened from the bank, the START card of the board showed the layout's placeholders (grey dummy
-- portrait, the two white _icon_card01 / _icon_card02 quads, the leader / position marks). The retail OnInit asks the
-- player's slot in that dock (funcLuaCommand(1131797651, hdl, 40, false, false, dock, kind)); for a player outside
-- the dock the native getter (0xC721C0, case 0x28) walks the 29 slots, finds nothing and pushes no value, so the slot
-- is nil, and UpdateAbilityLearningBoardCharaCard dies on its first line (`a5 >= 16`) before the native card draw
-- (3837561292) and before it hides those quads. The formation never opens the board for an outsider, so retail never
-- hits it. Here a missing slot becomes 255 = «not in the dock» (no starter / bench / manager range): the card is drawn
-- with the player's best position, as for any player outside a team.
-- Hook file (graft [[hooks]]): the screen has no VR-Framework host, so the global is wrapped directly, once per VM
-- (Utilities' combo partners wrap the same global: the wrappers chain). No engine call at chunk load.
do
  UTIL_BANK_BOARD = UTIL_BANK_BOARD or {}
  local U = UTIL_BANK_BOARD
  U.NO_SLOT = 255
  U.logged = false
  local cur = rawget(_ENV, "UpdateAbilityLearningBoardCharaCard")
  if type(cur) == "function" and not U.wrapped then
    U.wrapped = true
    -- (charaStHdl, showTeamDockNo, teamDockType, formationId, selectCharaIdx, isScout)
    rawset(_ENV, "UpdateAbilityLearningBoardCharaCard", function(a1, a2, a3, a4, a5, ...)
      if type(a5) ~= "number" then
        if not U.logged then
          U.logged = true
          pcall(funcLuaCommand, 3661580131 --[[CMND_EVT_LOG]], "utilities bank_commands", "board card: player not in dock",
            a2, "kind", a3, "chara", a1, "slot", tostring(a5), "->", U.NO_SLOT)
        end
        a5 = U.NO_SLOT
      end
      return cur(a1, a2, a3, a4, a5, ...)
    end)
  end
end
